                            grid[ny][nx] == 2 and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            objects.append(cells)

    objects.sort(key=lambda cells: min(x for y, x in cells))
    n = len(objects)
    out = [row[:] for row in grid]

